// deps[p] = list of projects that p imports (p depends on them).
var deps = {
  web: ['ui'],
  ui: ['utils'],
  api: ['utils'],
  utils: [],
  docs: []
};

function affected(deps, changed) {
  // TODO: return every project that is changed OR transitively depends on a
  // changed one, by walking REVERSE edges (dependents). Return a sorted array.
  return Array.from(new Set(changed)).sort();
}

function keyFor(p, changedSet) {
  return p + ':' + (changedSet.has(p) ? 'dirty' : 'clean');
}

function plan(deps, changed, cachedKeys) {
  var changedSet = new Set(changed);
  var aff = affected(deps, changed);
  var cached = new Set(cachedKeys);
  var lines = ['AFFECTED: ' + aff.join(', ')];
  for (var i = 0; i < aff.length; i++) {
    var p = aff[i];
    var hit = cached.has(keyFor(p, changedSet));
    lines.push((hit ? 'RESTORE ' : 'RUN     ') + p);
  }
  return lines.join('\n');
}

// utils changed; ui's clean build was cached by a teammate earlier.
var changed = ['utils'];
var cachedKeys = ['ui:clean'];
console.log(plan(deps, changed, cachedKeys));

tasks.starter:
// nx.json — a namedInput meant to invalidate only projects that read shared config
{
  "namedInputs": {
    "sharedConfig": ["{workspaceRoot}/**/*"]   // <-- something here is too broad
  },
  "targetDefaults": {
    "build": { "inputs": ["default", "sharedConfig"] }
  }
}

model.en:
Affected isn't broken — the namedInput is mis-scoped. A `{workspaceRoot}` glob is a GLOBAL input: any file matching it is treated as touching every project, so `{workspaceRoot}/**/*` matches literally every file in the repo and turns every edit into a full-repo affected set (the same blast radius you get from the lockfile or tsconfig.base.json by design). The fix is to point the glob at only the genuinely shared files, e.g. `{workspaceRoot}/tsconfig.base.json` and `{workspaceRoot}/config/shared.json`, not `**/*`:

```json
"namedInputs": {
  "sharedConfig": [
    "{workspaceRoot}/tsconfig.base.json",
    "{workspaceRoot}/config/shared.json"
  ]
}
```

Now only edits to those specific files invalidate everything; an ordinary src edit affects just its project and dependents. Switching to build-all would 'fix' the symptom by making CI uniformly slow again — the exact problem affected exists to solve. Keep the global inputs as narrow as truth allows: a file should be global only if changing it can really affect every project.

model.ru:
Affected не сломан — namedInput неверно очерчен. Glob `{workspaceRoot}` — это ГЛОБАЛЬНЫЙ вход: любой файл под ним считается затрагивающим каждый проект, так что `{workspaceRoot}/**/*` матчит буквально каждый файл репозитория и превращает любую правку в affected-набор на весь репозиторий (тот же радиус поражения, что по замыслу дают lock-файл или tsconfig.base.json). Фикс — нацелить glob лишь на действительно общие файлы, например `{workspaceRoot}/tsconfig.base.json` и `{workspaceRoot}/config/shared.json`, а не `**/*`:

```json
"namedInputs": {
  "sharedConfig": [
    "{workspaceRoot}/tsconfig.base.json",
    "{workspaceRoot}/config/shared.json"
  ]
}
```

Теперь только правки этих конкретных файлов инвалидируют всё; обычная правка src затрагивает лишь свой проект и зависящих. Переход на build-all «починил» бы симптом, снова сделав CI равномерно медленным — ровно ту проблему, ради которой существует affected. Держи глобальные входы настолько узкими, насколько позволяет правда: файл должен быть глобальным, только если его изменение реально может затронуть каждый проект.
